#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <errno.h>
#include <ctype.h>
#include <regex.h>
#include <fnmatch.h>
#include <libgen.h>
#include <pwd.h>
#include <grp.h>
#include <time.h>
#include <limits.h>

/* ---------- small dynamic array/string helpers ---------- */
typedef struct {
    char *s;
    size_t len, cap;
} str_t;

static void str_init(str_t *s) { s->s = NULL; s->len = 0; s->cap = 0; }
static void str_free(str_t *s) { free(s->s); s->s = NULL; s->len = s->cap = 0; }
static void str_reserve(str_t *s, size_t need) {
    if (need <= s->cap) return;
    size_t c = s->cap ? s->cap : 16;
    while (c < need) c *= 2;
    s->s = realloc(s->s, c);
    s->cap = c;
}
static void str_append_n(str_t *s, const char *data, size_t n) {
    str_reserve(s, s->len + n + 1);
    memcpy(s->s + s->len, data, n);
    s->len += n;
    s->s[s->len] = 0;
}
static void str_append(str_t *s, const char *data) { str_append_n(s, data, strlen(data)); }
static void str_append_c(str_t *s, char c) { str_reserve(s, s->len + 2); s->s[s->len++] = c; s->s[s->len] = 0; }

typedef struct {
    char **items;
    size_t len, cap;
} strarr_t;

static void sa_init(strarr_t *a) { a->items = NULL; a->len = 0; a->cap = 0; }
static void sa_free(strarr_t *a) {
    for (size_t i = 0; i < a->len; i++) free(a->items[i]);
    free(a->items);
    a->items = NULL;
    a->len = a->cap = 0;
}
static void sa_push(strarr_t *a, const char *s) {
    if (a->len == a->cap) {
        a->cap = a->cap ? a->cap * 2 : 8;
        a->items = realloc(a->items, a->cap * sizeof(char*));
    }
    a->items[a->len++] = strdup(s);
}
static void sa_push_take(strarr_t *a, char *s) {
    if (a->len == a->cap) {
        a->cap = a->cap ? a->cap * 2 : 8;
        a->items = realloc(a->items, a->cap * sizeof(char*));
    }
    a->items[a->len++] = s;
}

static int cmp_strptr(const void *a, const void *b) {
    const char *A = *(const char * const*)a;
    const char *B = *(const char * const*)b;
    return strcmp(A, B);
}

/* ---------- program state (options) ---------- */
typedef enum {
    PATTERN_REGEX,
    PATTERN_GLOB,
    PATTERN_FIXED,
} pattern_mode_t;

typedef enum {
    CASE_SMART,
    CASE_SENSITIVE,
    CASE_INSENSITIVE,
} case_mode_t;

typedef enum {
    COLOR_AUTO,
    COLOR_ALWAYS,
    COLOR_NEVER,
} color_mode_t;

typedef struct {
    /* flags */
    bool hidden;
    bool no_ignore;
    bool no_ignore_vcs;
    bool no_require_git;
    bool no_ignore_parent;
    int unrestricted_count;
    case_mode_t case_mode;
    pattern_mode_t pat_mode;
    bool absolute_path;
    bool follow_links;
    bool full_path;
    bool print0;
    int max_depth;          /* -1 means unlimited */
    int min_depth;
    bool prune;
    bool list_details;
    bool quiet;
    bool show_errors;
    bool one_file_system;
    bool strip_cwd_auto;    /* default when -x/-X/-0 */
    int strip_cwd_prefix;   /* 0=auto, 1=always, 2=never */
    int max_results;        /* -1 unlimited */
    int threads;
    color_mode_t color;
    color_mode_t hyperlink;
    char *path_separator;
    char *base_directory;
    char *format_template;
    /* patterns */
    char *pattern;
    strarr_t and_patterns;
    /* filters */
    strarr_t extensions;
    strarr_t types;         /* 'f','d','l','s','p','b','c','x','e' */
    strarr_t excludes;
    strarr_t ignore_files;
    strarr_t ignore_contain;
    /* size */
    bool has_size_filters;
    /* time */
    bool has_time_newer, has_time_older;
    time_t t_newer, t_older;
    /* size filters list */
    strarr_t size_filters;
    /* owner filter */
    char *owner_filter;
    /* paths */
    strarr_t search_paths;
    /* exec */
    strarr_t exec_cmd;      /* flat list with command parts, ends of sublists separated... */
    int exec_mode;          /* 0=none, 1=exec (parallel), 2=exec-batch */
    int batch_size;
} opts_t;

static opts_t O;

/* ---------- logging ---------- */
static void fd_error(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "[fd error]: ");
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}
