}

static void arg_error_unexpected(const char *arg) {
    fprintf(stderr, "error: unexpected argument '%s' found\n", arg);
    fprintf(stderr, "\n  tip: to pass '%s' as a value, use '-- %s'\n", arg, arg);
    print_usage_hint();
    exit(2);
}
static void arg_error_missing_value(const char *opt, const char *meta) {
    fprintf(stderr, "error: a value is required for '%s <%s>' but none was supplied\n", opt, meta);
    fprintf(stderr, "\nFor more information, try '--help'.\n");
