}

/* ============================================================
 * Duration / time parsing
 * ============================================================ */
/* returns 1 if parsed OK */
static int parse_duration(const char *s, long *secs_out) {
    /* format: <num><unit>[<num><unit>...] OR "<num>weeks" */
    const char *p = s;
    long total = 0;
    bool any = false;
    while (*p) {
        while (*p == ' ') p++;
        if (!*p) break;
        char *endp;
        long num = strtol(p, &endp, 10);
        if (endp == p) return 0;
        p = endp;
        char unit[16] = {0};
        int i = 0;
        while (*p && isalpha((unsigned char)*p) && i < 15) unit[i++] = tolower((unsigned char)*p++);
        if (i == 0) return 0;
        long mult = 0;
        if (!strcmp(unit, "s") || !strcmp(unit, "sec") || !strcmp(unit, "secs") || !strcmp(unit, "second") || !strcmp(unit, "seconds")) mult = 1;
        else if (!strcmp(unit, "m") || !strcmp(unit, "min") || !strcmp(unit, "mins") || !strcmp(unit, "minute") || !strcmp(unit, "minutes")) mult = 60;
        else if (!strcmp(unit, "h") || !strcmp(unit, "hr") || !strcmp(unit, "hrs") || !strcmp(unit, "hour") || !strcmp(unit, "hours")) mult = 3600;
        else if (!strcmp(unit, "d") || !strcmp(unit, "day") || !strcmp(unit, "days")) mult = 86400;
        else if (!strcmp(unit, "w") || !strcmp(unit, "week") || !strcmp(unit, "weeks")) mult = 7*86400;
        else if (!strcmp(unit, "mo") || !strcmp(unit, "month") || !strcmp(unit, "months")) mult = 30*86400;
        else if (!strcmp(unit, "y") || !strcmp(unit, "year") || !strcmp(unit, "years")) mult = 365*86400;
        else return 0;
        total += num * mult;
        any = true;
    }
    if (!any) return 0;
    *secs_out = total;
    return 1;
}

/* parse either @timestamp, YYYY-MM-DD, YYYY-MM-DD HH:MM:SS, or duration
 * returns absolute seconds (time_t) in out, 1 if ok */
static int parse_time_arg(const char *s, time_t *out) {
    if (s[0] == '@') {
        char *endp;
        long v = strtol(s+1, &endp, 10);
        if (*endp) return 0;
        *out = (time_t)v;
        return 1;
    }
    /* try YYYY-MM-DD optional time */
    struct tm tm;
    memset(&tm, 0, sizeof(tm));
    char *rest = strptime(s, "%Y-%m-%d %H:%M:%S", &tm);
    if (!rest) { memset(&tm, 0, sizeof(tm)); rest = strptime(s, "%Y-%m-%d", &tm); }
    if (rest && *rest == 0) {
        tm.tm_isdst = -1;
        time_t t = mktime(&tm);
        if (t == (time_t)-1) return 0;
        *out = t;
        return 1;
    }
    /* duration -> now - duration */
    long secs;
    if (parse_duration(s, &secs)) {
        *out = time(NULL) - secs;
        return 1;
    }
    return 0;
}

/* ============================================================
 * Size constraint parsing
 * ============================================================ */
typedef struct {
    char sign;      /* '+', '-', '=' */
    long long bytes;
} size_filter_t;

static int parse_size_constraint(const char *s, size_filter_t *f) {
    char sign = '=';
    const char *p = s;
    if (*p == '+' || *p == '-') { sign = *p++; }
    char *endp;
    long long num = strtoll(p, &endp, 10);
    if (endp == p || num < 0) return 0;
    p = endp;
    char unit[8] = {0};
    int i = 0;
