static const char *accepted_types[] = {
    "file", "directory", "symlink", "block-device", "char-device",
    "executable", "empty", "socket", "pipe", NULL
};

static const char *normalize_type(const char *v) {
    if (!strcmp(v, "f") || !strcmp(v, "file")) return "f";
    if (!strcmp(v, "d") || !strcmp(v, "dir") || !strcmp(v, "directory")) return "d";
    if (!strcmp(v, "l") || !strcmp(v, "symlink")) return "l";
    if (!strcmp(v, "x") || !strcmp(v, "executable")) return "x";
    if (!strcmp(v, "e") || !strcmp(v, "empty")) return "e";
    if (!strcmp(v, "s") || !strcmp(v, "socket")) return "s";
    if (!strcmp(v, "p") || !strcmp(v, "pipe")) return "p";
    if (!strcmp(v, "b") || !strcmp(v, "block-device")) return "b";
    if (!strcmp(v, "c") || !strcmp(v, "char-device")) return "c";
    return NULL;
}

static const char *parse_color_value(const char *v) {
    if (!strcmp(v, "auto")) return "auto";
    if (!strcmp(v, "always")) return "always";
    if (!strcmp(v, "never")) return "never";
    return NULL;
}

