    memset(m, 0, sizeof(*m));
    m->mode = mode;
    bool ci = false;
    if (cm == CM_INSENS) ci = true;
    else if (cm == CM_SMART) ci = !str_has_upper(pattern);
    m->case_insensitive = ci;
    if (mode == PM_REGEX) {
        int flags = REG_EXTENDED | REG_NOSUB;
        if (ci) flags |= REG_ICASE;
        int rc = regcomp(&m->rx, pattern, flags);
