    while (len > 0 && (p[len-1] == ' ' || p[len-1] == '\t' || p[len-1] == '\r' || p[len-1] == '\n')) {
        if (len >= 2 && p[len-2] == '\\') break;
        len--;
    }
    if (len == 0) return;
    char buf[4096];
    if (len >= sizeof(buf)) len = sizeof(buf)-1;
    memcpy(buf, p, len); buf[len] = 0;
    bool negate = false;
    char *q = buf;
    if (*q == '!') { negate = true; q++; }
    bool dir_only = false;
    if (buf[len-1] == '/') { dir_only = true; buf[--len] = 0; }
    bool anchored = false;
    if (*q == '/') { anchored = true; q++; }
    /* path pattern if contains slash */
    bool path_pattern = strchr(q, '/') != NULL;
    if (path_pattern) anchored = true;
    if (f->n == f->cap) {
        f->cap = f->cap ? f->cap * 2 : 16;
        f->rules = realloc(f->rules, f->cap * sizeof(ig_rule_t));
    }
    f->rules[f->n].pattern = strdup(q);
    f->rules[f->n].negate = negate;
    f->rules[f->n].dir_only = dir_only;
    f->rules[f->n].anchored = anchored;
    f->rules[f->n].path_pattern = path_pattern;
    f->n++;
}

static int load_ig_file(ig_file_t *f, const char *path, const char *base) {
    FILE *fp = fopen(path, "r");
    if (!fp) return 0;
    memset(f, 0, sizeof(*f));
    f->base = strdup(base);
    char line[8192];
    while (fgets(line, sizeof(line), fp)) {
        igf_add(f, line);
    }
    fclose(fp);
    return 1;
}

static void igf_free(ig_file_t *f) {
    for (size_t i = 0; i < f->n; i++) free(f->rules[i].pattern);
    free(f->rules);
    free(f->base);
    memset(f, 0, sizeof(*f));
}

/* Simple glob match used for gitignore patterns (like fnmatch but ** supported) */
static bool gitignore_match_glob(const char *pat, const char *text, bool path_pattern) {
    /* Implement a subset: *, **, ?, [..] */
    const char *p = pat;
    const char *s = text;
    const char *p_bt = NULL, *s_bt = NULL;
    bool slash_ok = false;

    while (*s) {
        if (*p == '*') {
            if (p[1] == '*') {
                slash_ok = true;
                p += 2;
                if (*p == '/') p++;
            } else {
                slash_ok = !path_pattern;
                p++;
            }
            p_bt = p;
            s_bt = s;
            continue;
        }
        if (*p == '?' && *s != '/') {
            p++; s++;
            continue;
        }
        if (*p == '[') {
            const char *pc = p + 1;
            bool neg = false;
            if (*pc == '!' || *pc == '^') { neg = true; pc++; }
            bool matched = false;
            while (*pc && *pc != ']') {
                char lo = *pc, hi = lo;
                if (pc[1] == '-' && pc[2] && pc[2] != ']') { hi = pc[2]; pc += 3; } else pc++;
                if ((unsigned char)*s >= (unsigned char)lo && (unsigned char)*s <= (unsigned char)hi) matched = true;
            }
            if (*pc == ']') pc++;
            if (matched != neg && *s != '/') {
                p = pc; s++;
                continue;
            }
        } else if (*p == '\\' && p[1]) {
            if (p[1] == *s) { p += 2; s++; continue; }
        } else if (*p == *s) {
            p++; s++;
            continue;
        }
        /* mismatch */
        if (p_bt) {
            if (!slash_ok && *s_bt == '/') return false;
            s_bt++;
            if (!slash_ok && s_bt[-1] == '/') return false;
            p = p_bt; s = s_bt;
            continue;
        }
        return false;
    }
    while (*p == '*') {
        if (p[1] == '*') p += 2; else p++;
        if (*p == '/') p++;
    }
    return *p == 0;
}

/* Match one gitignore file against a relative path and type
 * Returns: 0 = not matched, 1 = ignore, -1 = unignored (negated) */
static int igf_match(const ig_file_t *f, const char *relpath, bool is_dir) {
    int result = 0;
    /* iterate; later rules override earlier */
    for (size_t i = 0; i < f->n; i++) {
        const ig_rule_t *r = &f->rules[i];
        if (r->dir_only && !is_dir) continue;
        bool m = false;
        if (r->anchored) {
            m = gitignore_match_glob(r->pattern, relpath, r->path_pattern);
        } else {
            /* non-anchored: can match any trailing path component */
            const char *p = relpath;
            while (p) {
                if (gitignore_match_glob(r->pattern, p, r->path_pattern)) { m = true; break; }
                p = strchr(p, '/');
                if (p) p++;
            }
        }
        if (m) result = r->negate ? -1 : 1;
    }
    return result;
}

/* Check a path against a stack of ignore files */
static bool ig_stack_match(const ig_stack_t *stack, const char *abs_path, bool is_dir) {
    int result = 0;
    /* iterate in stack order (top/outer first, deeper overrides) */
    for (size_t i = 0; i < stack->n; i++) {
        const ig_file_t *f = &stack->files[i];
        /* compute relative path from f->base */
        size_t bl = strlen(f->base);
        if (strncmp(abs_path, f->base, bl) != 0) continue;
        const char *rel = abs_path + bl;
        while (*rel == '/') rel++;
        if (!*rel) continue;
        int r = igf_match(f, rel, is_dir);
        if (r != 0) result = r;
    }
    return result == 1;
}

