/* ============================================================
 * Walk the filesystem
 * ============================================================ */

typedef struct {
    matcher_t main_match;
    matcher_t *and_matchers;
    size_t n_and;
    size_t total_results;
    strarr_t outputs; /* collected results if we need to sort */
    bool sort_results;
    bool need_output;
    /* size filters parsed */
    size_filter_t *size_filters_p;
    size_t n_size_filters;
} walker_state_t;

static bool type_allowed(mode_t m, off_t size, const char *name, const char *fullpath, struct stat *st, bool is_symlink) {
    (void)name;
    (void)fullpath;
    (void)st;
    if (O.types.len == 0) return true;
    bool want_file = false, want_dir = false, want_link = false;
    bool want_exec = false, want_empty = false;
    bool want_sock = false, want_pipe = false, want_blk = false, want_chr = false;
    for (size_t i = 0; i < O.types.len; i++) {
        char c = O.types.items[i][0];
        switch (c) {
        case 'f': want_file = true; break;
        case 'd': want_dir = true; break;
        case 'l': want_link = true; break;
        case 'x': want_exec = true; break;
        case 'e': want_empty = true; break;
        case 's': want_sock = true; break;
        case 'p': want_pipe = true; break;
        case 'b': want_blk = true; break;
        case 'c': want_chr = true; break;
        }
    }
    /* executable implies file if no file/dir specified */
    /* Behavior: 'executable' matches regular files with x bit; 'empty' matches empty files and/or dirs */
    bool is_reg = S_ISREG(m);
    bool is_dir_ = S_ISDIR(m);
    bool is_lnk = is_symlink;
    bool is_sock = S_ISSOCK(m);
    bool is_fifo = S_ISFIFO(m);
    bool is_blk = S_ISBLK(m);
    bool is_chr = S_ISCHR(m);

    bool ok = false;
    if (want_file && is_reg) ok = true;
    if (want_dir && is_dir_) ok = true;
    if (want_link && is_lnk) ok = true;
    if (want_sock && is_sock) ok = true;
    if (want_pipe && is_fifo) ok = true;
    if (want_blk && is_blk) ok = true;
    if (want_chr && is_chr) ok = true;
    if (want_exec) {
        if (is_reg && (m & (S_IXUSR | S_IXGRP | S_IXOTH))) ok = true;
    }
    if (want_empty) {
        if (is_reg && size == 0) ok = true;
        if (is_dir_) {
            /* need to check empty */
            DIR *d = opendir(fullpath);
            if (d) {
                bool empty = true;
                struct dirent *de;
                while ((de = readdir(d))) {
                    if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
                    empty = false; break;
                }
                closedir(d);
                if (empty) {
                    /* if user specified type file or dir besides empty, intersect */
                    /* when empty is specified alongside file or dir, result is AND */
                    if (want_file || want_dir) {
                        if (want_dir) ok = true;
                    } else ok = true;
                }
            }
        } else if (is_reg && size == 0) {
            if (!(want_file || want_dir)) ok = true;
            else if (want_file) ok = true;
        }
    }
    return ok;
}

static bool extension_allowed(const char *name) {
    if (O.extensions.len == 0) return true;
    const char *dot = strrchr(name, '.');
    if (!dot || dot == name) return false;
    const char *ext = dot + 1;
    for (size_t i = 0; i < O.extensions.len; i++) {
        const char *e = O.extensions.items[i];
        while (*e == '.') e++;
        if (strcasecmp(ext, e) == 0) return true;
    }
    return false;
}

static bool exclude_matches(const char *relpath, const char *name, bool is_dir) {
    (void)is_dir;
    for (size_t i = 0; i < O.excludes.len; i++) {
        const char *pat = O.excludes.items[i];
        /* Match against basename AND full relative path */
        if (gitignore_match_glob(pat, name, false)) return true;
        if (strchr(pat, '/') && gitignore_match_glob(pat, relpath, true)) return true;
    }
    return false;
}

static bool size_allowed(off_t sz, walker_state_t *ws) {
    for (size_t i = 0; i < ws->n_size_filters; i++) {
        size_filter_t *f = &ws->size_filters_p[i];
        if (f->sign == '+') {
            if (sz < f->bytes) return false;
        } else if (f->sign == '-') {
            if (sz > f->bytes) return false;
        } else {
            if (sz != f->bytes) return false;
        }
    }
    return true;
}

static bool time_allowed(time_t mt) {
    if (O.has_time_newer && mt < O.t_newer) return false;
    if (O.has_time_older && mt > O.t_older) return false;
    return true;
}

/* Parse owner filter like [!]user:group where either part is optional.
 * We parse at check time since users/groups could change; simpler: parse at startup.
 */
typedef struct {
    bool has_user, user_neg, user_is_uid;
    uid_t uid;
    char *user_name;
    bool has_group, group_neg, group_is_gid;
    gid_t gid;
    char *group_name;
} owner_spec_t;

static bool owner_spec_parse(const char *s, owner_spec_t *o) {
    memset(o, 0, sizeof(*o));
    const char *colon = strchr(s, ':');
    const char *user_part = s;
    const char *group_part = colon ? colon + 1 : NULL;
    size_t user_len = colon ? (size_t)(colon - s) : strlen(s);
    if (user_len > 0) {
        char buf[256];
        if (user_len >= sizeof(buf)) user_len = sizeof(buf)-1;
        memcpy(buf, user_part, user_len); buf[user_len] = 0;
        char *u = buf;
        if (*u == '!') { o->user_neg = true; u++; }
        o->has_user = true;
        char *endp;
        long uid = strtol(u, &endp, 10);
        if (*endp == 0 && endp != u) { o->uid = (uid_t)uid; o->user_is_uid = true; }
        else { o->user_name = strdup(u); }
    }
    if (group_part && *group_part) {
        char buf[256];
        size_t gl = strlen(group_part);
        if (gl >= sizeof(buf)) gl = sizeof(buf)-1;
        memcpy(buf, group_part, gl); buf[gl] = 0;
        char *g = buf;
        if (*g == '!') { o->group_neg = true; g++; }
        o->has_group = true;
        char *endp;
        long gid = strtol(g, &endp, 10);
        if (*endp == 0 && endp != g) { o->gid = (gid_t)gid; o->group_is_gid = true; }
        else { o->group_name = strdup(g); }
    }
    return true;
}

static bool owner_matches(uid_t uid, gid_t gid, const owner_spec_t *o) {
    if (o->has_user) {
        uid_t target;
        if (o->user_is_uid) target = o->uid;
        else {
            struct passwd *pw = getpwnam(o->user_name);
            if (!pw) return false;
            target = pw->pw_uid;
        }
        bool eq = (uid == target);
        if (eq == o->user_neg) return false;
    }
    if (o->has_group) {
        gid_t target;
        if (o->group_is_gid) target = o->gid;
        else {
            struct group *gr = getgrnam(o->group_name);
            if (!gr) return false;
            target = gr->gr_gid;
        }
        bool eq = (gid == target);
        if (eq == o->group_neg) return false;
    }
    return true;
}

