        }
    }
    buf_append(out, p);
    if (is_dir && (out->len == 0 || out->s[out->len-1] != '/')) {
        buf_append_c(out, '/');
    }
}

/* Check if a directory contains a file (for --ignore-contain) */
static bool dir_contains_any(const char *dir, strarr_t *names) {
    for (size_t i = 0; i < names->len; i++) {
        char buf[PATH_MAX];
        snprintf(buf, sizeof(buf), "%s/%s", dir, names->items[i]);
        struct stat st;
        if (lstat(buf, &st) == 0) return true;
    }
    return false;
}

/* Build absolute path */
static char *abspath_of(const char *p) {
    if (p[0] == '/') return strdup(p);
    char cwd[PATH_MAX];
    if (!getcwd(cwd, sizeof(cwd))) return strdup(p);
    size_t need = strlen(cwd) + 1 + strlen(p) + 1;
    char *out = malloc(need);
    snprintf(out, need, "%s/%s", cwd, p);
    return out;
}

/* Determine if we're in a git repo by walking upwards from given dir */
static bool is_in_git_repo(const char *dir) {
    char buf[PATH_MAX];
    strncpy(buf, dir, sizeof(buf)-1); buf[sizeof(buf)-1] = 0;
    /* resolve absolute */
    if (buf[0] != '/') {
        char cwd[PATH_MAX];
        if (getcwd(cwd, sizeof(cwd))) {
            size_t n = strlen(cwd) + 1 + strlen(buf) + 1;
            char *c = malloc(n);
            snprintf(c, n, "%s/%s", cwd, buf);
            strncpy(buf, c, sizeof(buf)-1); buf[sizeof(buf)-1] = 0;
            free(c);
        }
    }
    while (1) {
        char g[PATH_MAX];
        snprintf(g, sizeof(g), "%s/.git", buf);
        struct stat st;
        if (lstat(g, &st) == 0) return true;
        /* parent */
        char *sl = strrchr(buf, '/');
        if (!sl) break;
        if (sl == buf) { buf[1] = 0; snprintf(g, sizeof(g), "/.git"); if (lstat(g, &st) == 0) return true; break; }
        *sl = 0;
        if (!*buf) break;
    }
    return false;
}

typedef struct {
    const char *root_print;    /* how to print paths under this root (may be "." or absolute) */
    const char *root_abs;      /* absolute path of root */
    dev_t root_dev;            /* for one-file-system */
} root_info_t;

static walker_state_t WS;

static void add_result(const char *path, bool is_dir) {
    buf_t b;
    buf_init(&b);
    format_print_path(path, is_dir, &b);
    /* Store result */
    if (WS.outputs.len == WS.outputs.cap) {
        WS.outputs.cap = WS.outputs.cap ? WS.outputs.cap * 2 : 64;
        WS.outputs.items = realloc(WS.outputs.items, WS.outputs.cap * sizeof(char*));
    }
    WS.outputs.items[WS.outputs.len++] = strdup(b.s);
    buf_free(&b);
}

static bool pattern_matches(const char *name, const char *relpath, bool is_dir) {
    (void)is_dir;
    const char *target = O.full_path ? relpath : name;
    if (!matcher_match(&WS.main_match, target, O.full_path)) return false;
    for (size_t i = 0; i < WS.n_and; i++) {
        if (!matcher_match(&WS.and_matchers[i], target, O.full_path)) return false;
    }
    return true;
}

/* walker main recursion */
static void walk_dir(const char *path_abs, const char *path_print, int depth, ig_stack_t *stack, dev_t root_dev) {
    if (O.max_depth >= 0 && depth > O.max_depth) return;
    DIR *dir = opendir(path_abs);
    if (!dir) {
        if (O.show_errors) fd_error("Could not read directory '%s': %s", path_abs, strerror(errno));
        return;
    }

    /* Check if ignore files exist in this directory, push onto stack */
    int pushed = 0;
    if (!O.no_ignore) {
        const char *ig_names[] = { ".gitignore", ".ignore", ".fdignore", NULL };
        for (int k = 0; ig_names[k]; k++) {
            if (O.no_ignore_vcs && !strcmp(ig_names[k], ".gitignore")) continue;
            char p[PATH_MAX];
            snprintf(p, sizeof(p), "%s/%s", path_abs, ig_names[k]);
            struct stat st;
            if (lstat(p, &st) == 0 && S_ISREG(st.st_mode)) {
                ig_file_t f;
                if (load_ig_file(&f, p, path_abs)) {
                    if (stack->n == stack->cap) {
                        stack->cap = stack->cap ? stack->cap*2 : 8;
                        stack->files = realloc(stack->files, stack->cap * sizeof(ig_file_t));
                    }
                    stack->files[stack->n++] = f;
                    pushed++;
                }
            }
        }
    }

    /* collect entries */
    strarr_t names;
    sa_init(&names);
    struct dirent *de;
    while ((de = readdir(dir))) {
        if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
        sa_push(&names, de->d_name);
    }
    closedir(dir);
    qsort(names.items, names.len, sizeof(char*), cmp_strptr);

    for (size_t i = 0; i < names.len; i++) {
        const char *name = names.items[i];
        /* max results check */
        if (O.max_results >= 0 && (int)WS.outputs.len >= O.max_results) break;
        /* hidden */
        if (!O.hidden && name[0] == '.') continue;
        char child_abs[PATH_MAX];
        snprintf(child_abs, sizeof(child_abs), "%s/%s", path_abs, name);
        char child_print[PATH_MAX];
        if (!strcmp(path_print, "") || !strcmp(path_print, "/")) {
            snprintf(child_print, sizeof(child_print), "%s%s", path_print, name);
        } else if (path_print[strlen(path_print)-1] == '/') {
            snprintf(child_print, sizeof(child_print), "%s%s", path_print, name);
        } else {
            snprintf(child_print, sizeof(child_print), "%s/%s", path_print, name);
        }

        struct stat lst;
        if (lstat(child_abs, &lst) != 0) {
            if (O.show_errors) fd_error("Could not get metadata for '%s': %s", child_abs, strerror(errno));
            continue;
        }
        bool is_symlink = S_ISLNK(lst.st_mode);
        struct stat st = lst;
        if (is_symlink && O.follow_links) {
            if (stat(child_abs, &st) != 0) {
                if (O.show_errors) fd_error("broken symlink '%s'", child_abs);
                continue;
            }
        }
        mode_t m = O.follow_links ? st.st_mode : lst.st_mode;
        bool is_dir = S_ISDIR(m);
        off_t sz = lst.st_size;

        /* one_file_system */
        if (O.one_file_system && lst.st_dev != root_dev) continue;

        /* excludes apply first (override ignore) */
        bool excluded = exclude_matches(child_print, name, is_dir);
        if (excluded) continue;

        /* gitignore */
        if (!O.no_ignore) {
            if (ig_stack_match(stack, child_abs, is_dir)) continue;
        }

        /* ignore-contain (only for directories) */
        if (is_dir && O.ignore_contain.len > 0) {
            if (dir_contains_any(child_abs, &O.ignore_contain)) continue;
        }

        /* Apply filters for inclusion */
        bool include = true;

        /* depth */
        if (depth + 1 < O.min_depth) include = false;

        /* pattern */
        if (include && O.pattern_set) {
            if (!pattern_matches(name, child_print, is_dir)) include = false;
        }

        /* type */
        if (include && !type_allowed(m, sz, name, child_abs, &st, is_symlink)) include = false;

        /* extension */
        if (include && !extension_allowed(name)) include = false;

        /* size */
        if (include && WS.n_size_filters > 0 && S_ISREG(m)) {
            if (!size_allowed(sz, &WS)) include = false;
        } else if (include && WS.n_size_filters > 0 && !S_ISREG(m)) {
            /* only apply to regular files? original fd applies to files and counts 0 for dirs */
            /* Simplest: skip for non-files */
            include = false;
        }

        /* time */
        if (include && (O.has_time_newer || O.has_time_older)) {
            if (!time_allowed(lst.st_mtime)) include = false;
        }

        /* owner */
        if (include && O.owner_filter) {
            static owner_spec_t osp;
            static bool parsed = false;
            if (!parsed) { owner_spec_parse(O.owner_filter, &osp); parsed = true; }
            if (!owner_matches(lst.st_uid, lst.st_gid, &osp)) include = false;
        }

        if (include) {
            add_result(child_print, is_dir);
        }

        /* recursion: skip for symlink to dir unless follow */
        if (is_dir && (!is_symlink || O.follow_links)) {
            /* prune: if the dir matched, don't recurse */
            if (O.prune && include) continue;
            walk_dir(child_abs, child_print, depth + 1, stack, root_dev);
            if (O.max_results >= 0 && (int)WS.outputs.len >= O.max_results) break;
        }
    }
    sa_free(&names);

    /* pop pushed ignore files */
    for (int i = 0; i < pushed; i++) {
        igf_free(&stack->files[--stack->n]);
    }
}

