 * ============================================================ */

/* Substitute placeholders in one argument with a single path */
static char *substitute_placeholders(const char *templ, const char *path, bool *had_placeholder) {
    buf_t out;
    buf_init(&out);
    const char *p = templ;
    while (*p) {
        if (p[0] == '{' && p[1] == '{') {
            buf_append_c(&out, '{');
            p += 2; continue;
        }
        if (p[0] == '}' && p[1] == '}') {
            buf_append_c(&out, '}');
            p += 2; continue;
        }
        if (p[0] == '{') {
            const char *end = strchr(p, '}');
            if (end) {
                size_t plen = end - p - 1;
                char spec[8] = {0};
                if (plen < sizeof(spec)) {
                    memcpy(spec, p + 1, plen);
                    spec[plen] = 0;
                }
                if (had_placeholder) *had_placeholder = true;
                const char *sub_path = path;
                /* compute basename and parent */
                char pathcopy1[PATH_MAX], pathcopy2[PATH_MAX];
                strncpy(pathcopy1, sub_path, sizeof(pathcopy1)-1); pathcopy1[sizeof(pathcopy1)-1]=0;
                strncpy(pathcopy2, sub_path, sizeof(pathcopy2)-1); pathcopy2[sizeof(pathcopy2)-1]=0;
                const char *bname = basename(pathcopy1);
                const char *dname = dirname(pathcopy2);
                /* path without extension */
                char no_ext[PATH_MAX];
                strncpy(no_ext, sub_path, sizeof(no_ext)-1); no_ext[sizeof(no_ext)-1]=0;
                char *dot = strrchr(no_ext, '.');
                char *slash = strrchr(no_ext, '/');
                if (dot && (slash == NULL || dot > slash) && dot != no_ext && (slash == NULL || dot != slash+1)) *dot = 0;
                char bname_no_ext[PATH_MAX];
                strncpy(bname_no_ext, bname, sizeof(bname_no_ext)-1); bname_no_ext[sizeof(bname_no_ext)-1]=0;
                char *d2 = strrchr(bname_no_ext, '.');
                if (d2 && d2 != bname_no_ext) *d2 = 0;

                if (!strcmp(spec, "")) buf_append(&out, sub_path);
                else if (!strcmp(spec, "/")) buf_append(&out, bname);
                else if (!strcmp(spec, "//")) buf_append(&out, dname);
                else if (!strcmp(spec, ".")) buf_append(&out, no_ext);
                else if (!strcmp(spec, "/.")) buf_append(&out, bname_no_ext);
                else {
                    /* Unknown - keep literal */
                    buf_append_n(&out, p, end - p + 1);
                }
                p = end + 1;
                continue;
            }
        }
        buf_append_c(&out, *p);
        p++;
    }
    char *r = strdup(out.s ? out.s : "");
    buf_free(&out);
    return r;
}

static void exec_for_path(const char *path) {
    if (O.exec_argv.len == 0) return;
    bool any_placeholder = false;
    /* Pre-scan to see if any arg has placeholder */
    for (size_t i = 0; i < O.exec_argv.len; i++) {
        const char *t = O.exec_argv.items[i];
        const char *p = t;
        while (*p) {
            if (p[0] == '{' && p[1] == '{') { p += 2; continue; }
            if (p[0] == '}' && p[1] == '}') { p += 2; continue; }
            if (p[0] == '{') { const char *e = strchr(p, '}'); if (e) { any_placeholder = true; break; } }
            p++;
        }
        if (any_placeholder) break;
    }
    char **argv = calloc(O.exec_argv.len + 2, sizeof(char*));
    size_t n = 0;
    for (size_t i = 0; i < O.exec_argv.len; i++) {
        argv[n++] = substitute_placeholders(O.exec_argv.items[i], path, NULL);
    }
    if (!any_placeholder) {
        argv[n++] = strdup(path);
    }
    argv[n] = NULL;

    pid_t pid = fork();
    if (pid == 0) {
        execvp(argv[0], argv);
        fprintf(stderr, "[fd error]: Could not execute '%s': %s\n", argv[0], strerror(errno));
        _exit(127);
    } else if (pid > 0) {
        int st;
        waitpid(pid, &st, 0);
    }
    for (size_t i = 0; i < n; i++) free(argv[i]);
    free(argv);
}

static void exec_batch(strarr_t *paths) {
    if (O.exec_argv.len == 0 || paths->len == 0) return;
    /* split into batches */
    size_t bs = O.batch_size ? O.batch_size : paths->len;
    for (size_t s = 0; s < paths->len; s += bs) {
        size_t end = s + bs;
        if (end > paths->len) end = paths->len;

        /* For each template arg: if it contains a placeholder, expand
         * per-path into many argv entries; else include literally. */
        strarr_t argv;
        sa_init(&argv);
        bool any_placeholder = false;
        for (size_t i = 0; i < O.exec_argv.len; i++) {
            const char *t = O.exec_argv.items[i];
            bool has = false;
            const char *p = t;
            while (*p) {
                if (p[0] == '{' && p[1] == '{') { p += 2; continue; }
                if (p[0] == '}' && p[1] == '}') { p += 2; continue; }
                if (p[0] == '{') { const char *e = strchr(p, '}'); if (e) { has = true; break; } }
                p++;
            }
            if (has) {
                any_placeholder = true;
                for (size_t k = s; k < end; k++) {
                    char *sub = substitute_placeholders(t, paths->items[k], NULL);
                    sa_push(&argv, sub); free(sub);
                }
            } else {
                sa_push(&argv, t);
            }
        }
        if (!any_placeholder) {
            for (size_t k = s; k < end; k++) sa_push(&argv, paths->items[k]);
        }
        char **av = calloc(argv.len + 1, sizeof(char*));
        for (size_t i = 0; i < argv.len; i++) av[i] = argv.items[i];
        av[argv.len] = NULL;
        pid_t pid = fork();
        if (pid == 0) {
            execvp(av[0], av);
            fprintf(stderr, "[fd error]: Could not execute '%s': %s\n", av[0], strerror(errno));
            _exit(127);
        } else if (pid > 0) {
            int stt;
            waitpid(pid, &stt, 0);
        }
        free(av);
        sa_free(&argv);
    }
}

