/* ============================================================
 * main
 * ============================================================ */
int main(int argc, char **argv) {
    parse_args(argc, argv);

    /* base-directory */
    if (O.base_directory) {
        if (chdir(O.base_directory) != 0) {
            fd_error("Could not change directory to '%s': %s", O.base_directory, strerror(errno));
            return 1;
        }
    }

    /* determine list of search roots */
    strarr_t roots;
    sa_init(&roots);
    if (O.search_paths.len > 0) {
        for (size_t i = 0; i < O.search_paths.len; i++) sa_push(&roots, O.search_paths.items[i]);
    } else if (O.path_args.len > 0) {
        for (size_t i = 0; i < O.path_args.len; i++) sa_push(&roots, O.path_args.items[i]);
    } else {
        sa_push(&roots, ".");
    }

    /* validate roots */
    strarr_t valid_roots;
    sa_init(&valid_roots);
    for (size_t i = 0; i < roots.len; i++) {
        struct stat st;
        if (stat(roots.items[i], &st) != 0) {
            fd_error("Search path '%s' is not a directory.", roots.items[i]);
            continue;
        }
        if (!S_ISDIR(st.st_mode)) {
            fd_error("Search path '%s' is not a directory.", roots.items[i]);
            continue;
        }
        sa_push(&valid_roots, roots.items[i]);
    }
    if (valid_roots.len == 0) {
        fd_error("No valid search paths given.");
        return 1;
    }
    sa_free(&roots);

    /* build matchers */
    memset(&WS, 0, sizeof(WS));
    const char *pat = O.pattern_set ? O.pattern : "";
    matcher_init(&WS.main_match, pat, O.pat_mode, O.case_mode);
    WS.n_and = O.and_patterns.len;
    if (WS.n_and) {
        WS.and_matchers = calloc(WS.n_and, sizeof(matcher_t));
        for (size_t i = 0; i < WS.n_and; i++) matcher_init(&WS.and_matchers[i], O.and_patterns.items[i], O.pat_mode, O.case_mode);
    }

    /* parse size filters */
    WS.n_size_filters = O.size_filters.len;
    if (WS.n_size_filters) {
        WS.size_filters_p = calloc(WS.n_size_filters, sizeof(size_filter_t));
        for (size_t i = 0; i < WS.n_size_filters; i++) parse_size_constraint(O.size_filters.items[i], &WS.size_filters_p[i]);
    }

    /* decide color actual */
    if (O.color == COL_ALWAYS) use_color_actual = true;
    else if (O.color == COL_NEVER) use_color_actual = false;
    else use_color_actual = isatty(STDOUT_FILENO);

    /* effective exec mode: list-details implies exec-batch with ls -lhd --color=always */
    bool list_details_mode = O.list_details;
    if (list_details_mode) {
        if (O.exec_mode == 0) {
            O.exec_mode = 2;
            sa_push(&O.exec_argv, "ls");
            sa_push(&O.exec_argv, "-lhd");
            sa_push(&O.exec_argv, "--color=always");
        }
    }

    /* gitignore: also consider global ignore files (~/.config/fd/ignore etc.) - skipped */
    /* ignore-file option: add these as a low-precedence rule set */
    ig_stack_t stack;
    memset(&stack, 0, sizeof(stack));
    if (!O.no_ignore) {
        for (size_t i = 0; i < O.ignore_files.len; i++) {
            ig_file_t f;
            char base[PATH_MAX];
            strncpy(base, O.ignore_files.items[i], sizeof(base)-1); base[sizeof(base)-1]=0;
            char *sl = strrchr(base, '/');
            if (sl) *sl = 0; else strcpy(base, ".");
            char abspath[PATH_MAX];
            if (realpath(base, abspath) == NULL) strncpy(abspath, base, sizeof(abspath)-1);
            if (load_ig_file(&f, O.ignore_files.items[i], abspath)) {
                if (stack.n == stack.cap) {
                    stack.cap = stack.cap ? stack.cap*2 : 8;
                    stack.files = realloc(stack.files, stack.cap * sizeof(ig_file_t));
                }
                stack.files[stack.n++] = f;
            }
        }
    }

    /* For each root: set up, walk */
    for (size_t r = 0; r < valid_roots.len; r++) {
        const char *root = valid_roots.items[r];
        /* derive how paths under this root should be printed */
        char print_base[PATH_MAX];
        if (O.absolute_path) {
            char *ap = abspath_of(root);
            strncpy(print_base, ap, sizeof(print_base)-1); print_base[sizeof(print_base)-1]=0;
            free(ap);
        } else {
            strncpy(print_base, root, sizeof(print_base)-1); print_base[sizeof(print_base)-1]=0;
        }
        /* remove trailing / if not root "/" */
        size_t pl = strlen(print_base);
        while (pl > 1 && print_base[pl-1] == '/') print_base[--pl] = 0;

        /* absolute root for walking */
        char *abs_root = abspath_of(root);
        struct stat rst;
        stat(root, &rst);

        /* gitignore / require-git handling */
        bool respect_ignore = !O.no_ignore;
        if (respect_ignore && !O.no_require_git && !is_in_git_repo(abs_root)) {
            /* Only global ignore is respected; we don't have it - behave as if no ignore for simplicity? */
            /* But we still want to parse .ignore/.fdignore by default? fd actually does respect them always */
            /* Keep respect_ignore on, but .gitignore-specific rules still applied. */
        }

        /* handle min-depth=0 case: the root itself isn't typically printed */
        walk_dir(abs_root, print_base, 0, &stack, rst.st_dev);
        free(abs_root);
    }

    /* Sort and output */
    if (!O.quiet) {
        qsort(WS.outputs.items, WS.outputs.len, sizeof(char*), cmp_strptr);
    }

    bool had_any = WS.outputs.len > 0;

    if (O.quiet) {
        /* do not print */
    } else if (O.exec_mode == 0) {
        char sep = O.print0 ? 0 : '\n';
        for (size_t i = 0; i < WS.outputs.len; i++) {
            fputs(WS.outputs.items[i], stdout);
            fputc(sep, stdout);
        }
    } else if (O.exec_mode == 1) {
        for (size_t i = 0; i < WS.outputs.len; i++) exec_for_path(WS.outputs.items[i]);
    } else if (O.exec_mode == 2) {
        exec_batch(&WS.outputs);
    }

    /* Exit code */
    int exit_code = 0;
    if (O.quiet) exit_code = had_any ? 0 : 1;

    /* cleanup (best-effort) */
    matcher_free(&WS.main_match);
    for (size_t i = 0; i < WS.n_and; i++) matcher_free(&WS.and_matchers[i]);
    free(WS.and_matchers);
    free(WS.size_filters_p);
    for (size_t i = 0; i < WS.outputs.len; i++) free(WS.outputs.items[i]);
    free(WS.outputs.items);
    for (size_t i = 0; i < stack.n; i++) igf_free(&stack.files[i]);
    free(stack.files);

    return exit_code;
}
